# TRAP: Never use mutable default arguments like def bad_func(items=[])!
def good_func(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

# Keyword-only arguments after '*'
def configure_server(host, port, *, debug=False, timeout=30):
    return f"Server at {host}:{port} (debug={debug}, timeout={timeout}s)"

def main():
    print("=== 06: Functions, Mutable Default Trap & Closures ===")
    print(good_func("A"))
    print(good_func("B"))
    print(configure_server("127.0.0.1", 8000, debug=True))

if __name__ == "__main__":
    main()

import functools
import time

def timing_decorator(func):
    @functools.wraps(func) # Preserves original function __name__ and __doc__
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        duration = time.perf_counter() - start
        print(f"Function '{func.__name__}' executed in {duration:.6f}s")
        return result
    return wrapper

@timing_decorator
def compute_squares(n):
    return [x**2 for x in range(n)]

def main():
    print("=== 07: Decorators & Metaprogramming ===")
    res = compute_squares(100_000)
    print(f"Squares computed: {len(res)}")

if __name__ == "__main__":
    main()

class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self

    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        val = self.current
        self.current -= 1
        return val

def main():
    print("=== 09: Comprehensions & Custom Iterator Protocol ===")
    even_squares = [x**2 for x in range(10) if x % 2 == 0]
    print(f"List Comprehension: {even_squares}")

    print("Custom Iterator:")
    for num in Countdown(3):
        print(f"Count: {num}")

if __name__ == "__main__":
    main()

def fibonacci_generator(limit):
    a, b = 0, 1
    for _ in range(limit):
        yield a
        a, b = b, a + b

def main():
    print("=== 10: Generators, Yield & Memory-Efficient Pipelines ===")
    fib = list(fibonacci_generator(8))
    print(f"First 8 Fibonacci numbers: {fib}")

if __name__ == "__main__":
    main()

class Vector:
    __slots__ = ("x", "y") # Optimizes memory by preventing per-instance __dict__

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __repr__(self):
        return f"Vector(x={self.x}, y={self.y})"

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

def main():
    print("=== 11: OOP, Dunder Methods & __slots__ Optimization ===")
    v1 = Vector(2, 3)
    v2 = Vector(5, 7)
    v3 = v1 + v2
    print(f"Vector Addition: {v3}")

if __name__ == "__main__":
    main()

class ValidationError(Exception):
    """Custom business validation exception."""
    pass

def validate_age(age):
    if age < 0:
        raise ValidationError(f"Age cannot be negative: {age}")
    return True

def main():
    print("=== 13: Error & Exception Handling Architecture ===")
    try:
        validate_age(-5)
    except ValidationError as e:
        print(f"Caught Custom Error: {e}")
    finally:
        print("Cleanup block executed.")

if __name__ == "__main__":
    main()

from contextlib import contextmanager

@contextmanager
def managed_resource(name):
    print(f"Acquiring resource: {name}")
    try:
        yield name.upper()
    finally:
        print(f"Releasing resource: {name}")

def main():
    print("=== 14: Context Managers & the 'with' Statement ===")
    with managed_resource("db_connection") as res:
        print(f"Inside with block using: {res}")

if __name__ == "__main__":
    main()

from typing import Optional, Union, Sequence

def get_user_name(user_id: int, fallback: Optional[str] = None) -> str:
    if user_id == 1:
        return "Navnath"
    return fallback or "Anonymous"

def main():
    print("=== 15: Static Typing & Type Hints (PEP 484-695) ===")
    print("User 1:", get_user_name(1))
    print("User 2:", get_user_name(2, fallback="Guest"))

if __name__ == "__main__":
    main()

